SELECT p.id, p.symbol, p.side, p.status, p.quantity, p.entry_price, p.stop_loss, p.take_profit, p.exit_price, p.realized_pnl, p.signal_id, p.exit_signal_id, p.close_reason, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(p.opened_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS opened_utc, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(p.closed_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS closed_utc, ROUND(UNIX_TIMESTAMP(p.closed_at)-UNIX_TIMESTAMP(p.opened_at),3) AS hold_s, ROUND((p.entry_price-p.stop_loss)/p.entry_price*100,4) AS stop_pct, ROUND((p.take_profit-p.entry_price)/p.entry_price*100,4) AS target_pct, ROUND((p.exit_price-p.entry_price)/p.entry_price*100,4) AS exit_move_pct, LEFT(p.entry_reason,800) AS entry_reason_800, LEFT(p.exit_reason,800) AS exit_reason_800 FROM paper_position p WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id;